struct Foo {
    Type1 member1;
    Type2 member2;
};

struct Date {
    int year;
    int month;
    int day;
};

struct Birthday {
    char name[50];
    struct Date dob;
};

struct Person {
    char name[50];
    int age;
    struct {
        char city[50];
        int zip;
    } addr;
};

struct LinkedList {
    void* item; // stores the current item
    struct LinkedList* next; // stores the next list, or NULL if nothing next
};

struct B;

struct A {
    struct B* b;
};

struct B {
    struct A* a;
};

typedef struct Foo {
    Type1 member1;
    Type2 member2;
} Foo;

// struct Foo can now be referred to as 'Foo'
Foo foo;

struct Point {
    int x;
    int y;
};

struct Point a = { .x = 1, .b = 2 };

// May initialize fields out of order too
struct Point b = { .y = 4, .x = -3 };

struct Point a = { 1, 3 };
struct Point b;
b = a;

struct Properties {
    // three fields can be compactly packed in one byte
    unsigned char visible : 1; // a occupies 1 bit
    unsigned char color : 3; // b occupies 3 bits
    unsigned char size : 4; // c occupies 4 bits
};

struct Point p = { 3, 7 };
int x = p.x;
p.x = 10;
struct Point* pp = &p;
x = pp->x;
pp->x = 8;

#include <stdio.h>

// a larger struct which may carry a lot of data
struct Student {
    char name[50];
    unsigned int id;
    unsigned int semester;
    float gpa;
};

// passing by value
void print_student(struct Student s) {
    printf("Name: %s, ID: %d, in semester %d, with GPA: %.2f\n", s.name, s.id, s.semester, s.gpa);
}

// passing by pointer
void print_student(struct Student* s) {
    printf("Name: %s, ID: %d, in semester %d, with GPA: %.2f\n", s->name, s->id, s->semester, s->gpa);
}
